id (French official name: État de la rémunération payée) of the Canada Revenue Agency (CRA). Slip issued by employers showing an employee's employment income and the deductions taken during the year. \"T4\" is the official form code – keep it as is. Canadian forms.", "t": {"de": "T4-Formular online ausfüllen | Bescheinigung über gezahlte Vergütungen | PDF Help", "es": "Rellena el formulario T4 en línea | Estado de remuneración pagada | PDF Help", "fr": "Remplissez le formulaire T4 en ligne | État de la rémunération payée | PDF Help", "it": "Compila il modulo T4 online | Prospetto della retribuzione pagata | PDF Help", "ko": "온라인으로 T4 양식 작성 | 급여 지급 명세서 | PDF Help", "ms": "Isi borang T4 dalam talian | Penyata saraan dibayar | PDF Help", "nl": "T4-formulier online invullen | Overzicht van uitbetaalde beloning | PDF Help", "pt": "Preencha o formulário T4 online | Demonstrativo de remuneração paga | PDF Help", "sv": "Fyll i T4-formulär online | Kontrolluppgift över utbetald ersättning | PDF Help", "th": "กรอกแบบฟอร์ม T4 ออนไลน์ | ใบแจ้งค่าตอบแทนที่จ่าย | PDF Help", "vi": "Điền mẫu T4 trực tuyến | Bảng kê thù lao đã trả | PDF Help"}}, "969345852": {"en": "Fill in a Canada Revenue Agency T4 statement of remuneration paid. Enter employment income and deductions, then download a PDF.", "d": "SEO meta description (search results snippet). Recommended max ~160 characters. Not visible on the page. For the T4 landing page (/t4-form). T4 – Statement of Remuneration Paid (French official name: État de la rémunération payée) of the Canada Revenue Agency (CRA). Slip issued by employers showing an employee's employment income and the deductions taken during the year. \"T4\" is the official form code – keep it as is. Canadian forms.", "t": {"de": "Fülle eine T4-Bescheinigung über gezahlte Vergütungen der kanadischen Steuerbehörde (CRA) aus. Gib Einkünfte aus Beschäftigung und Abzüge ein und lade dann ein PDF herunter.", "es": "Rellena un estado de remuneración pagada T4 de la Agencia de Ingresos de Canadá (CRA). Introduce los ingresos laborales y las deducciones y, después, descarga un PDF.", "fr": "Remplissez un État de la rémunération payée T4 de l'Agence du revenu du Canada. Saisissez les revenus d'emploi et les retenues, puis téléchargez un PDF.", "it": "Compila un prospetto T4 della retribuzione pagata dell'Agenzia delle entrate canadese (CRA). Inserisci i redditi da lavoro dipendente e le trattenute, poi scarica un PDF.", "ko": "캐나다 국세청(CRA)의 T4 급여 지급 명세서를 작성하세요. 근로소득과 공제 항목을 입력한 다음 PDF를 다운로드하세요.", "ms": "Isi penyata saraan dibayar T4 Agensi Hasil Kanada (CRA). Masukkan pendapatan penggajian dan potongan, kemudian muat turun PDF.", "nl": "Vul een T4-overzicht van uitbetaalde beloning van de Canadese belastingdienst (CRA) in. Voer inkomsten uit dienstverband en inhoudingen in en download daarna een pdf.", "pt": "Preencha um demonstrativo de remuneração paga T4 da Receita do Canadá (CRA). Informe a renda do trabalho e as deduções e depois baixe um PDF.", "sv": "Fyll i en T4, det kanadensiska skatteverkets (CRA) kontrolluppgift över utbetald ersättning. Ange inkomst av anställning och avdrag och ladda sedan ner en PDF.", "th": "กรอกใบแจ้งค่าตอบแทนที่จ่าย T4 ของกรมสรรพากรแคนาดา (CRA) ระบุรายได้จากการจ้างงานและรายการหักต่าง ๆ แล้วดาวน์โหลด PDF", "vi": "Điền bảng kê thù lao đã trả T4 của Cơ quan Thuế vụ Canada (CRA). Nhập thu nhập từ việc làm và các khoản khấu trừ, sau đó tải xuống tệp PDF."}}, "969345853": {"en": "Complete the CRA T4 statement of remuneration paid in PDF Help and download a PDF.", "d": "Social sharing (Open Graph) description, shown when the page link is shared. Not visible on the page. For the T4 landing page (/t4-form). T4 – Statement of Remuneration Paid (French official name: État de la rémunération payée) of the Canada Revenue Agency (CRA). Slip issued by employers showing an employee's employment income and the deductions taken during the year. \"T4\" is the official form code – keep it as is. Canadian forms.", "t": {"de": "Fülle mit PDF Help die T4-Bescheinigung der CRA über gezahlte Vergütungen aus und lade ein PDF herunter.", "es": "Completa el estado de remuneración pagada T4 de la CRA en PDF Help y descarga un PDF.", "fr": "Remplissez l'État de la rémunération payée T4 de l'ARC avec PDF Help et téléchargez un PDF.", "it": "Compila il prospetto T4 della retribuzione pagata della CRA con PDF Help e scarica un PDF.", "ko": "PDF Help에서 캐나다 국세청(CRA) T4 급여 지급 명세서를 작성하고 PDF를 다운로드하세요.", "ms": "Lengkapkan penyata saraan dibayar T4 CRA dalam PDF Help dan muat turun PDF.", "nl": "Vul het T4-overzicht van uitbetaalde beloning van de CRA in met PDF Help en download een pdf.", "pt": "Preencha o demonstrativo de remuneração paga T4 da CRA no PDF Help e baixe um PDF.", "sv": "Fyll i CRA:s T4-kontrolluppgift över utbetald ersättning med PDF Help och ladda ner en PDF.", "th": "กรอกใบแจ้งค่าตอบแทนที่จ่าย T4 ของ CRA ใน PDF Help แล้วดาวน์โหลด PDF", "vi": "Điền bảng kê thù lao đã trả T4 của CRA trong PDF Help và tải xuống tệp PDF."}}}};
for (const id in S.K) { const k = S.K[id]; if (k.plural) continue; for (const l of S.LANGS) { if (typeof k.t[l] !== 'string' || !k.t[l].trim()) throw new Error('missing ' + id + ' ' + l); } }
if (Object.keys(S.K).length !== 11) throw new Error('expected 11 keys');
return [{ json: { langs: S.LANGS, ids: Object.keys(S.K).join(','), K: S.K } }];

const MODE = 'all'; // 'check' | 'test' | 'all'
const cfg = $('Config').first().json;
const b = $input.first().json.body || {};
if (!Array.isArray(b.keys)) { throw new Error('Guard fetch failed: ' + JSON.stringify(b).slice(0, 300)); }
const items = []; const skip = [];
for (const k of b.keys) {
  const spec = cfg.K[String(k.key_id)]; if (!spec) { continue; }
  if (k.is_archived) { skip.push([k.key_id, 'archived']); continue; }
  const m = {}; for (const t of (k.translations || [])) { m[t.language_iso] = typeof t.translation === 'string' ? t.translation : JSON.stringify(t.translation); }
  const it = { key_id: k.key_id };
  if (String(k.description || '').trim()) { skip.push([k.key_id, 'description already set']); } else { it.description = spec.d; }
  if (!spec.plural) {
    if (k.is_plural) { skip.push([k.key_id, 'unexpected plural']); continue; }
    if ((m.en || '') !== spec.en) { skip.push([k.key_id, 'EN changed']); continue; }
    const tr = [];
    for (const iso of cfg.langs) {
      if (String(m[iso] || '').trim()) { skip.push([k.key_id, iso, 'already filled']); continue; }
      tr.push({ language_iso: iso, translation: spec.t[iso], is_unverified: true });
    }
    if (tr.length) { it.translations = tr; }
  }
  if (it.description || it.translations) { items.push(it); }
}
const found = b.keys.filter(function (k) { return cfg.K[String(k.key_id)]; }).length;
let sel = items;
if (MODE === 'check') { sel = []; }
if (MODE === 'test') { sel = items.filter(function (x) { return String(x.key_id) === '969345843'; }).map(function (x) { const o = { key_id: x.key_id, translations: (x.translations || []).filter(function (t) { return t.language_iso === 'de'; }) }; if (x.description) { o.description = x.description; } return o; }); }
const n = sel.reduce(function (a, x) { return a + (x.translations || []).length; }, 0);
const nd = sel.filter(function (x) { return x.description; }).length;
return [{ json: { mode: MODE, keys_expected: Object.keys(cfg.K).length, keys_found: found, translations_to_write: n, descriptions_to_write: nd, skipped: skip, nkeys: sel.length, body: JSON.stringify({ keys: sel }) } }];

const cfg = $('Config').first().json;
const mode = $('Build writes').first().json.mode;
const b = $input.first().json.body || {};
if (!Array.isArray(b.keys)) { return [{ json: { error: 'read-back failed' } }]; }
let match = 0, empty = 0, dmatch = 0, dother = 0, dempty = 0; const diff = [];
for (const k of b.keys) {
  const spec = cfg.K[String(k.key_id)]; if (!spec) { continue; }
  if (k.description === spec.d) { dmatch++; } else if (String(k.description || '').trim()) { dother++; diff.push([k.key_id, 'description', String(k.description).slice(0, 80)]); } else { dempty++; }
  if (spec.plural) { continue; }
  const m = {}; for (const t of (k.translations || [])) { m[t.language_iso] = t; }
  for (const iso of cfg.langs) { const v = (m[iso] || {}).translation; if (v === spec.t[iso]) { match++; } else if (!String(v || '').trim()) { empty++; } else { diff.push([k.key_id, iso, String(v).slice(0, 100)]); } }
  if ((m.en || {}).translation !== spec.en) { diff.push([k.key_id, 'en', 'EN differs']); }
}
let w = [];
try { w = $('WRITE').all().map(function (x) { return { status: x.json.statusCode, written: ((x.json.body || {}).keys || []).length, errors: (x.json.body || {}).errors || (x.json.body || {}).error || null }; }); } catch (e) { w = 'not run'; }
return [{ json: { mode: mode, write: w, readback: { translations_match: match, still_empty: empty, different: diff, descriptions_match: dmatch, descriptions_other: dother, descriptions_empty: dempty } } }];
